                    "additionalProperties": false,
                    "properties": {
                      "name": {
                        "type": "string"
                      },
                      "type": {
                        "enum": [
                          "hash",
                          "text"
                        ],
                        "default": "hash",
                        "type": "string"
                      },
                      "password": {
                        "type": "string"
                      }
                    }
                  }
                ]
              }
            },
            "list": {
              "oneOf": [
                {
