    "cc_landscape": {
      "type": "object",
      "properties": {
        "landscape": {
          "type": "object",
          "required": ["client"],
          "properties": {
            "client": {
              "type": "object",
              "properties": {
                "url": {
                  "type": "string",
                  "default": "https://landscape.canonical.com/message-system",
                  "description": "The Landscape server URL to connect to. Default: ``https://landscape.canonical.com/message-system``."
                },
                "ping_url": {
