                "server": {
                  "type": "object"
                },
                "agent": {
                  "type": "object"
                },
                "user": {
                  "type": "object"
                },
                "ca_cert": {
                  "type": "string"
                }
              }
            },
            "csr_attributes": {
              "type": "object",
              "description": "create a ``csr_attributes.yaml`` file for CSR attributes and certificate extension requests. See https://puppet.com/docs/puppet/latest/config_file_csr_attributes.html",
              "additionalProperties": false,
              "properties": {
                "custom_attributes": {
                  "type": "object"
                },
                "extension_requests": {
                  "type": "object"
                }
              }
            }
          }
        }
      }
